// 保留基于分享聊天文字回复的考点复述；用户后补的 8 道截图原题位于 weak-focus.js。
// 题干、选项和补充条件由本站编写，不保留私人聊天、图片或身份资料。
export const phoneExamNotice='这 33 题根据手机分享聊天的文字回复复述，题干和选项已重新编写。另行提供的 8 道不熟练原题已录入“我的薄弱题”，包含完整宏题；其余截图原题尚未逐字核对。这里保留考点复述与补充条件，原题和同类训练可在薄弱题专题一起练习。';
export const phoneChoices=[];
export const phoneWritten=[];
const source='手机笔试 · 考点复述';
function M(order,id,lesson,prompt,code,options,answer,steps,difficulty='基础',trace){
 phoneChoices.push({id:'phone-'+id,lesson,prompt,code,options,answer,steps,explain:steps.join('\n'),difficulty,source,batch:'phone',shareOrder:order,trace});
}
function W(order,id,lesson,title,prompt,code,answer,steps,rubric,difficulty='基础',trace){
 phoneWritten.push({id:'phone-'+id,lesson,title,prompt,code,answer,steps,rubric,kind:'填空 / 简答',difficulty,source,batch:'phone',shareOrder:order,trace});
}

W(1,'oop','cpp-virtual','C++ 面向对象的三个常见特征','写出三个常见特征，并分别用一句话解释。','','封装、继承、多态。封装组织数据与操作并限制访问；继承建立类之间的关系；多态让统一接口表现出不同的行为。',[
 '封装：例如电机类把速度作为状态，用 setSpeed 操作它；把需要保护的成员设为 private，调用者通过接口修改。封装的重点是管理访问和约束，不只是把变量放进 class。',
 '继承：例如 StepperMotor 从 Motor 公有派生，可以复用基类接口。公有继承通常表达“是一种”；不是所有代码复用都适合用继承。',
 '运行时多态：通过 Motor 指针或引用调用虚函数 run，实际执行哪个覆盖版本取决于对象的动态类型。函数重载属于另一种常说的静态多态。'
],['写出三个特征','能区分继承和多态','说明虚函数、基类指针或引用的作用']);
W(2,'build','mem-startup','从 C 源码到可执行文件','按通常的 GCC 构建流程填写四个阶段，并写出各阶段处理什么。这里没有使用原截图的空格编号。','','预处理 → 编译 → 汇编 → 链接。',[
 '预处理：处理 #include、#define 与条件编译，得到展开后的源码。gcc -E main.c 可以观察这一阶段。',
 '编译：完成语法、类型检查和代码生成，通常输出汇编代码；gcc -S main.c 得到 .s 文件。实际工具链可以合并内部阶段，图示是便于理解的流程。',
 '汇编：把汇编指令转换成目标文件 .o，里面还有符号和重定位信息；gcc -c main.c 会走到目标文件阶段。',
 '链接：组合目标文件与库、解析外部符号和重定位。MCU 工程还需链接脚本规定 Flash/SRAM 布局；链接成功后也仍需启动代码初始化运行环境。'
],['阶段顺序正确','区分 .s 与 .o','知道链接处理多个目标文件和符号'],'基础',{heads:['输入','处理','常见输出'],rows:[['main.c','预处理','展开后的 C 源码'],['展开后的 C 源码','编译','main.s'],['main.s','汇编','main.o'],['main.o + 其他 .o + 库','链接','可执行文件 / ELF']]} );
W(3,'macro-expanded','c-macro','无括号宏：先分析已知展开式','这里练习此前文字回复给出的展开式：最后 a 为多少？为什么？补充截图里的完整宏题已记录到“我的薄弱题”。','int a=10, k=2, m=1;\na /= k + m*k + m/k + m*k + m;','a = 1。右侧为 2+2+0+2+1=7，整数除法 10/7 得到 1。',[
 '先按实际语法分组：a /= (k + m*k + m/k + m*k + m)。复合赋值的右侧是完整表达式，不是先让 a 除以 k 再加其他项。',
 '乘除优先于加法，三个中间项依次是 m*k=2、m/k=0、m*k=2。m 和 k 都是 int，1/2 做整数除法，舍弃小数部分得到 0。',
 '右侧 2+2+0+2+1=7；a 最终取 10/7 的整数商 1。所有值均在 int 范围内，没有溢出或除零。',
 '宏首先替换 token，不能按“整体变量”直接套括号。补充截图已确认原宏为 SQR(X) X*X，调用式为 a/=SQR(k+m)/SQR(k+m)；完整原题与修复宏后的对比放在薄弱题专题。'
],['右侧计算为 7','说明整数除法','说明复合赋值的右侧分组'],'进阶',{heads:['项','代入','结果'],rows:[['k','2','2'],['m*k','1*2','2'],['m/k','1/2（整数）','0'],['m*k','1*2','2'],['m','1','1'],['最后 a','10 / (2+2+0+2+1)','1']]} );
W(4,'mask','c-bits','只保留 bit7 与 bit1','8 位数据中，从最低位 bit0 开始编号。只保留 bit7 与 bit1，其余位置零：写出二进制掩码、十六进制掩码与 C 表达式。','unsigned int x = 0xD7u;\n/* 写出 result 的计算式，并求值 */','掩码为 10000010（二进制），即 0x82。unsigned int result = x & 0x82u; 题设 result 为 0x82。',[
 '掩码位为 1 的位置保留原值，因为 b & 1 = b；为 0 的位置清零，因为 b & 0 = 0。因此要保留的 bit7、bit1 写 1，其他位写 0。',
 'bit7 对应 128，bit1 对应 2；128+2=130，十六进制为 0x82。也可以写 (1u<<7) | (1u<<1)。这是构造掩码时的按位或。',
 'x=0xD7 对应 11010111；与 10000010 按位与得到 10000010。保留某位不等于把那一位强制设为 1；如果原来该位是 0，保留后仍为 0。'
],['掩码位号正确','使用 & 保留位','求出 result'],'基础',{heads:['项目','bit7 … bit0'],rows:[['输入 x','1 1 0 1 0 1 1 1'],['保留掩码','1 0 0 0 0 0 1 0'],['按位与结果','1 0 0 0 0 0 1 0']]} );
W(5,'cast','c-conversion','强转之前还是之后做除法','将 x 转成 double 的 C 写法是什么？下面 r1、r2 分别是多少？这是在强转考点上补充的练习，代码由本站编写。','int x=3, y=2;\ndouble r1=(double)x / y;\ndouble r2=(double)(x / y);','转换写法是 (double)x。r1 为 1.5，r2 为 1.0。',[
 '括号内 double 是目标类型，后面的 x 是被转换的表达式。这个数值转换产生 double 类型的值，不改变 x 本身的 int 类型。',
 'r1 先把 x 转为 3.0，参与除法的 y 也转换为 double，3.0/2.0 得到 1.5。',
 'r2 的内层 x/y 先做整数除法，得到 1，再转换为 double 的 1.0。已经丢掉的小数部分不会因为后来强转或赋给 double 就回来。'
],['写出 C 强转形式','区分先除后转和先转后除','两项数值正确'],'进阶');
W(6,'plc','p-packet','PLC 电力线通信的传输介质','这里 PLC 指 Power Line Communication（电力线通信）。它主要利用什么介质传输数据？请说明它与“可编程逻辑控制器”这个缩写含义的区别。','','利用电力线（电源线）传输数据；PLC 在其他语境也可指 Programmable Logic Controller，不能只凭缩写判断。',[
 '电力线通信把承载信息的信号耦合到现有电力线路，两端用通信芯片调制与解调，所以介质仍是电线。它不是把普通供电电压高低直接当成 UART 字节。',
 '例如智能电表与集中器利用电力线传送计量数据。通信部分需处理噪声、衰减、阻抗变化和耦合电路，协议及频段需由系统具体规定。',
 'Programmable Logic Controller 是工业控制设备；Power Line Communication 是通信技术。两者共享 PLC 缩写，看到题目应先读全称和场景。'
],['回答电力线','知道需要调制解调','区分两种 PLC 含义']);
W(7,'debounce','stm32-gpio','按键消抖时间与实现','机械按键为什么需要消抖？入门实验常用什么量级的确认窗口？给出一种适合 RTOS 的做法。原回复给出 10～20 ms，这不是所有按键的固定规格。','','机械触点会在短时间内反复通断；10～20 ms 是常见入门设置，具体值应依据器件和实测波形。用定时采样或任务延后确认稳定电平，避免在 ISR 中长时间忙等。',[
 '按下动作虽然只有一次，触点却可能弹跳，GPIO 会读到多个边沿。直接把每个边沿当作一次按键就会重复触发。',
 '10～20 ms 可作为实验起点；若实际弹跳更久，窗口需调整。还需考虑响应延迟、按下和松开差异，不能把 20 ms 当成硬件统一保证。',
 '一种方法是任务每 1 ms 采样：若新采样与候选状态一致则累计，否则更新候选并重新计时；候选保持稳定达到窗口后才更新已确认状态、产生一次事件。',
 'EXTI 可以只记录事件或唤醒任务，再由任务定时确认。ISR 中循环延时会占据 CPU、拖延其他处理；RTOS 延时还需按 tick 配置换算，而不是假定 1 tick 永远等于 1 ms。'
],['说明触点弹跳','给出量级并注明需实测','避免 ISR 忙等','说明稳定确认策略'],'进阶');
W(8,'power-factor','stm32-adc','功率因数的范围与条件','对吸收有功功率的负载，按非负数值报告功率因数，且视在功率 S>0：PF 的范围和定义是什么？什么时候可写成 cosφ？','','0≤PF≤1；PF=P/S，S=电压有效值×电流有效值。正弦稳态电压、电流时 PF=cosφ；有谐波时一般不能仅用相位差代替真实功率因数。',[
 'P 是有功功率，单位 W；S 是视在功率，单位 VA。它们的比值没有单位，表示在给定有效值电压电流下有功功率占多大比例。',
 '本题限定负载吸收有功功率且用非负数值报告，范围为 0～1。S=0 时不能直接用 P/S；仪表显示方式需要查看规定。',
 '对正弦稳态，电压电流存在相位差 φ，可得 P=U有效值×I有效值×cosφ，所以 PF=cosφ。电流有谐波时还受到波形畸变影响，真实 PF 不一定等于基波 cosφ。',
 '有些仪表用正负号表示功率方向或超前/滞后，可能显示 -1～1。回答范围前要先读计量约定，不能把所有带符号读数都当成错误。'
],['0～1 与条件','PF=P/S 且无单位','cosφ 的适用条件'],'进阶');
W(9,'energy','stm32-adc','电能的“度”与 kWh','电表中的 1 度电是什么单位？恒定 2 kW 的负载运行半小时用了多少度电？','','1 度电=1 kWh（千瓦时）。2 kW×0.5 h=1 kWh，即 1 度。1 kWh=3.6×10^6 J。',[
 '功率描述消耗能量的速率，电能描述累计量。恒定功率下 E=P×t，功率单位 kW、时间单位 h 时，结果单位 kWh。',
 '半小时换成 0.5 h，再计算 2×0.5=1。kWh 的 h 是乘法中的时间，不是 kW/h；kW/h 表示功率随时间变化的量级。',
 '1 kW=1000 W，1 h=3600 s，且 W=J/s，因此 1 kWh=1000×3600 J。真实负载功率随时间变化时，需要分段累计或积分，不能只看铭牌瞬时功率。'
],['kWh 与度的关系','数值与单位正确','区分功率和电能']);

M(10,'offset','c-pointer','数组有 20 个元素，a[i]=i+1，p 指向 a[5]。p[7] 的值是多少？','int a[20];\nfor (int i=0; i<20; ++i) a[i]=i+1;\nint *p=&a[5];',['7','8','12','13'],3,[
 '下标表达式 p[7] 等价于 *(p+7)，从 p 当前指向的位置继续前进 7 个 int，而不是从数组第一个元素开始。',
 'p 从 a[5] 出发，到 a[5+7]=a[12]。加 7 移动的是 7 个元素；若 int 为 4 字节，对应 28 字节。',
 '数组初始化规律是 a[i]=i+1，所以 a[12]=13。下标 12 在 0～19 范围内；如果超出范围，不能只做加法给出有效读取结果。'
],'进阶',{heads:['表达式','位置','值'],rows:[['p / p[0]','a[5]','6'],['p+1 / p[1]','a[6]','7'],['p+7 / p[7]','a[12]','13']]} );
M(11,'guard','c-macro','下面头文件保护宏主要解决什么问题？','#ifndef SENSOR_H\n#define SENSOR_H\nstruct Sensor { int value; };\n#endif',['防止程序多次调用函数','避免同一翻译单元重复处理头文件内容','保证所有函数都被内联','自动避免多个 .c 中的全局变量重复定义'],1,[
 '第一次包含时 SENSOR_H 尚未定义，#ifndef 条件成立，处理结构体定义并定义 SENSOR_H。',
 '同一翻译单元再次包含时，这个宏已经存在，预处理器跳过包围的内容，避免同一个结构体定义被重复处理。',
 '各 .c 通常分别预处理，保护宏不能替代全局变量的 extern 声明与单独定义。若把全局变量定义放在头文件，多个目标文件仍可能产生链接问题。'
]);
M(12,'clear-bit','c-bits','flag 是普通 unsigned int 变量。将 bit2 清零、其他位保持原值，选哪条语句？bit0 为最低位。','unsigned int flag=0xAFu;',['flag |= 4u;','flag ^= 4u;','flag &= ~4u;','flag &= 4u;'],2,[
 'bit2 的权重是 2^2=4，4u 的低 8 位是 00000100；~4u 把该位置为 0，其余 unsigned int 位为 1。',
 'flag 与这个掩码按位与：bit2 不论原来是 0 还是 1，都变为 0；其他位与 1 运算，保持原值。0xAF 变为 0xAB。',
 '|= 会置位，^= 会翻转，&=4u 只保留 bit2。这些操作与“只清 bit2”不同。硬件 W1C 寄存器或并发更新不能直接套用普通变量的读改写，需要核对手册与同步策略。'
],'基础',{heads:['操作','低 8 位'],rows:[['flag 原值','1 0 1 0 1 1 1 1'],['~4u 的低 8 位','1 1 1 1 1 0 1 1'],['清 bit2 后','1 0 1 0 1 0 1 1']]} );
M(13,'list-insert','ds-list','在有效单链表中，将独立新节点 s 插入 p 后面。哪段代码正确保留原后继？p、s 均非空，s 不在原链表中。','/* 原链：p -> next -> ... */',['p->next=s; s->next=p->next;','s->next=p; p->next=s;','s->next=NULL; p->next=s;','s->next=p->next; p->next=s;'],3,[
 '先读出 p 原来的 next，保存到 s->next，这一步让新节点知道插入后要接到谁。',
 '再把 p->next 改为 s，链路成为 p → s → 原后继。若 p 原来是尾节点，s->next 得到 NULL，同样有效。',
 '若先 p->next=s，再 s->next=p->next，第二句读到的已经是 s，会令 s 指向自身，同时丢失原后继；顺序不能直接颠倒，除非提前用临时指针保存原后继。'
],'进阶',{heads:['阶段','连接'],rows:[['原来','p → next；s 独立'],['先保存后继','s → next；p → next'],['再接入新节点','p → s → next']]} );
M(14,'isr-work','r-isr','普通 MCU / FreeRTOS 工程里，哪组操作最应该从 ISR 移到任务或主循环处理？','',['读取状态、清中断源、使用允许的 FromISR 接口','长时间循环延时、普通 malloc、阻塞式 printf','记录时间戳并写入有容量检查的固定缓冲区','确认 DMA 完成标志并通知任务'],1,[
 'ISR 执行期间，同级或较低优先级中断通常不能立刻处理，长时间忙等会直接增加系统响应延迟。',
 '普通 malloc 或 printf 的实现可能使用锁、动态内存或慢速输出；被中断代码若正持有相同资源，还可能重入出错或死锁。不能假定普通库函数适合中断上下文。',
 '中断先完成必要的硬件确认、清标志和少量数据记录，再通过允许优先级下的 FromISR API 唤醒任务。专门设计的有界中断日志实现属于另一个条件，不能据此认为普通阻塞 printf 普遍安全。'
],'进阶');
M(15,'bubble','ds-sort','n≥2，冒泡排序每趟用 swapped 标志；一整趟没有交换就立即结束。输入已经非递减有序，元素比较次数是多少？','/* 每趟比较相邻元素；无交换则 break */',['n(n-1)/2','0','n-1','n'],2,[
 '第一趟依次比较 a[0] 与 a[1]、a[1] 与 a[2]，直到 a[n-2] 与 a[n-1]，一共 n-1 对。',
 '数组已经有序，没有相邻逆序项，所以没有交换。第一趟结束发现 swapped 为 false，算法终止。',
 '本题结果依赖提前结束优化：若固定执行全部趟数，常见实现仍比较 n(n-1)/2 次。带优化的最好时间为 O(n)，最坏时间仍为 O(n²)。'
],'进阶');
M(16,'process','os-schedule','在通常的进程 / 线程模型中，操作系统资源分配的基本单位是什么？','',['进程','线程','普通函数','源代码文件'],0,[
 '进程关联地址空间、文件描述符等资源，操作系统以进程为单位组织这些资源，因此教材通常把进程称为资源分配的基本单位。',
 '线程有自己的执行位置、寄存器上下文和栈，同一进程的线程通常共享地址空间与打开文件等资源。在支持线程的系统中，线程通常是 CPU 调度单位。',
 '函数只是程序内部代码组织方式，源码文件是构建组织方式，两者都不等于运行时进程。具体内核实现细节可不同，但不能把“分配资源”和“调度执行”混为一谈。'
]);
M(17,'structured','cpp-reference','关于 C++ 的编程方式，哪项正确？','',['C++ 要求每个函数都必须属于类','C++ 只支持面向对象，不能写循环','C++ 程序必须使用动态内存','C++ 也支持顺序、选择、循环和函数等结构化编程'],3,[
 '顺序执行语句、if 选择、for / while 循环和函数分解，都是结构化编程的常见工具，C++ 支持它们。',
 '一个使用 iostream 读入数字、循环求和再输出的 main 程序，即使没有自定义类，也可以是合法 C++ 程序。',
 '支持这些方式不代表任意 C 源码都能原样按 C++ 编译，例如隐式 void* 转换等规则不同。选择适合问题的方式即可，不需要为了合法性强行加入类或 new。'
]);
M(18,'public','cpp-virtual','Base::value 是 public，Derived 公有继承 Base。下列哪项描述正确？两个类及对象均可见。','class Base { public: int value=0; };\nclass Derived : public Base {};',['value 只有 Base 内部能访问','value 在 Base 内、Derived 内及类外通过相应对象均可访问','只要是 public，不论怎样继承都能通过派生对象从类外访问','value 自动变成静态成员'],1,[
 'public 成员允许类外通过对象访问，例如 Base b; b.value=1;。它没有因此变成 static，每个对象仍有自己的成员。',
 '本题明确 public 继承，基类公有成员在派生类中仍保持公有访问，因此 Derived d; d.value=2; 也合法。',
 '若改成 private 或 protected 继承，通过派生对象的类外访问规则会改变。不能脱离继承方式把“外部均可访问”写成无条件结论。'
],'进阶');
M(19,'pure-virtual','cpp-virtual','哪项是在基类内声明纯虚成员函数的正确常见写法？','',['void func()=1;','static virtual void func();','virtual void func()=0;','virtual void func(){}'],2,[
 'virtual 表示虚函数，声明末尾的 =0 是纯说明符，不是把函数的返回值设为零。',
 '如果类中仍有最终覆盖者为纯虚的函数，该类是抽象类，不能直接创建这个类的对象。派生类要成为可实例化类型，需要提供相应非纯覆盖实现。',
 'virtual void func(){} 是有函数体的普通虚函数。静态成员函数不依赖某个对象，不能同时声明为 virtual；纯虚函数也不等于“任何情况下绝对不能有定义”。'
]);
M(20,'context','arm-exception','处理中断之前保存寄存器等现场的主要目的是什么？','',['永久清空原程序的寄存器','把局部变量全部变成全局变量','保证中断处理不会使用 CPU','在处理后恢复必要状态，让被中断代码正确继续执行'],3,[
 '原程序可能正用寄存器保存地址、计数或中间计算值。ISR 也要使用寄存器；若不保护必要状态，返回后原程序就可能使用被改坏的数据。',
 'Cortex-M 异常入口由硬件保存基本帧中的 R0～R3、R12、LR、PC、xPSR，其他需保护的内容按编译器、调用约定和处理方式由软件管理，浮点场景还有扩展规则。',
 '恢复现场主要是恢复执行状态，并不把 ISR 对共享变量的合法写入撤销。任务切换也会保存上下文，但其后可能恢复另一个任务，不能把中断返回和调度切换混成同一动作。'
],'进阶');
M(21,'linear','ds-queue','下面哪项描述正确？二维数组的“行”作为有顺序的元素组来理解。','',['栈的取出顺序总是先进先出','链式存储在所有操作中都优于顺序存储','二维数组可以理解为数据元素本身是一行线性表的线性表','队列只能从尾部取出元素'],2,[
 '二维数组有按次序排列的各行，每行内部又是按次序排列的元素，因此可从“线性表的元素还是线性表”来理解。C 的二维数组本身是数组的数组，不是 int**。',
 '栈在同一端压入和弹出，后进先出；普通队列尾入头出，先进先出。两者的限制不同，不能互换口诀。',
 '顺序存储便于按下标访问，链式存储便于在已知节点处调整链接，但多了指针空间与访问开销。哪种更合适由操作和数据规模决定。'
]);
M(22,'critical','os-sync','需要互斥访问、一次只允许一个执行者进入使用的共享资源，通常叫什么？','',['临界区','临界资源','时间片','程序计数器'],1,[
 '临界资源是被保护的资源，例如同一外设或必须作为整体更新的共享记录。题目问的是“资源”本身。',
 '临界区是访问这份资源的代码段。资源和代码段相关，但术语指向不同对象，不能只记“临界”二字。',
 '互斥锁或合适的临界区机制用于限制并发访问。volatile 只涉及访问语义，不能自动让多个执行者互斥，也不能保证多条读改写语句成为一个原子操作。'
]);
M(23,'func-decl','c-funcptr','下面声明中 f 是什么？','int *f(int);',['参数为 int、返回 int* 的函数','指向返回 int 函数的指针变量','含 int 个元素的指针数组','返回 int 的函数'],0,[
 '从名字 f 开始读：右边紧接 (int)，说明 f 是函数，它有一个 int 参数。参数在声明中可以不写名字。',
 '再看左边 int *，这是函数返回类型，所以返回的是 int 指针；不是普通 int。',
 '对照 int (*f)(int)：括号先把 *f 结合起来，这才是指向函数的指针变量。int *f(int) 和 int (*f)(int) 不能只凭都含星号就认为一样。返回指针还需保证目标生命周期有效。'
],'进阶');
M(24,'enum','c-union','以下 C 枚举中，RED、GREEN、BLUE 的值分别是什么？','enum Color { RED, GREEN, BLUE };',['1、2、3','0、0、0','取决于 sizeof(enum Color)','0、1、2'],3,[
 '第一个没有显式赋值的枚举常量取 0；每个后续未显式赋值的枚举常量等于前一个的值加 1，所以依次为 0、1、2。',
 '若写 enum Color { RED=5, GREEN, BLUE };，则后两项从 5 继续加一，成为 6、7，并不是仍从 0 开始。',
 '枚举常量的值和 enum 对象的大小是两件事。不能从这三个常量的数值反推所有平台 sizeof(enum Color) 都相同。'
]);
M(25,'pointer-array','c-array-pointer','题设 sizeof(char*)=4。下面 files 占多少字节？','char *files[4];',['4','16','8','必须先知道每条字符串的长度'],1,[
 '名字 files 后面先结合 [4]，因此它是四元素数组；每个元素的类型是 char*。这叫指针数组。',
 'sizeof 数组等于元素数量乘元素大小，4×sizeof(char*)=4×4=16。数组里的指针是否初始化不影响这份数组对象的大小。',
 '指针所指字符串的数据放在别处，长度不计入这个数组的 sizeof。若指针改为 8 字节，结果为 32；只说操作系统位数不足以代替明确 ABI 条件。'
],'进阶');
M(26,'overload','cpp-reference','下面哪组在同一作用域中构成合法的普通函数重载？','',['int f(int);  double f(int);','void f(int x);  void f(int y);','void f(int);  void f(double);','void f(int);  void f(const int);'],2,[
 '普通函数重载可以使用同名而不同参数类型或数量的函数。本题 int 与 double 两种形参类型不同，构成重载。',
 '仅返回类型不同不能构成重载；调用 f(1) 时不能靠返回类型分辨。形参名字不同也只是改名，不会创建不同的函数。',
 '按值形参的顶层 const 不用于区分这里的函数类型，所以 void f(int) 与 void f(const int) 也不能这样重载。指向 const 的指针等底层限定属于另一个情形。'
],'进阶');
M(27,'padding','c-struct','题设 ABI：char 大小 / 对齐为 1，int 大小 / 对齐为 4；结构体整体按最大成员对齐，未开启打包。sizeof(struct S) 是多少？','struct S { char c1; int i; char c2; };',['6','9','10','12'],3,[
 'c1 从偏移 0 开始占 1 字节。i 的起点要是 4 的倍数，因此偏移 1、2、3 是填充，i 从偏移 4 占到 7。',
 'c2 的对齐只需 1，从偏移 8 开始占 1 字节。此时已使用 9 字节，但结构体总体对齐为 4，尾部再填充 3 字节，总共 12。',
 '尾部填充保证结构体数组里的下一项仍满足成员对齐。12 是由本题明确 ABI 推出的结果；成员大小相加 1+4+1=6 会漏掉中间和尾部填充。'
],'进阶',{heads:['偏移','内容','字节数'],rows:[['0','c1','1'],['1～3','中间填充','3'],['4～7','i','4'],['8','c2','1'],['9～11','尾部填充','3']]} );
M(28,'truth','c-start-expression','在 C 的 if 条件中，针对普通整数和有限浮点数，哪种数值被视为真？','',['只有 1','所有非零值','只有正整数','只有偶数'],1,[
 'if 判断表达式的值是否与零比较不相等。0 为假，非零为真，不要求数值必须等于 1。',
 '例如 if(-3) 和 if(0.5) 都进入分支，而 if(0) 不进入。题目特意限定普通数值，先掌握这一规则即可。',
 '条件判断和比较表达式的结果不同：a<b 这种比较本身产生 int 的 0 或 1，但直接用 a 当条件时，a 不需要先被改成 1。'
]);
M(29,'static-func','c-keywords','C 源文件中的文件作用域函数被 static 修饰，最准确的含义是什么？','static int helper(int x) { return x+1; }',['函数每次调用都重新编译','函数不能被传给回调接口','函数名具有内部链接，在本翻译单元内标识该函数','函数内所有局部变量都自动变成静态变量'],2,[
 'static 修饰文件作用域的函数定义，令函数名具有内部链接；另一个单独编译的 .c 不能用 extern 同名声明直接链接到这个内部函数。',
 '翻译单元通常是一个 .c 加上预处理展开进来的头文件，不应把这一概念严格等同于磁盘上只那一个 .c 的文本。',
 '内部链接并不禁止函数地址被返回或传到别处：外部代码仍可通过合法函数指针间接调用。函数中的普通局部变量也不会因函数被 static 修饰就自动具有静态存储期。'
],'进阶');
M(30,'array-inc','c-array','每个选项单独从初始 p=a 开始检查。哪项在 C 中非法？','int a[3]={10,20,30};\nint *p=a;',['a++','p+1','a+1','++p'],0,[
 'p 是一个可修改的指针变量，保存首元素地址；++p 改变 p，让它指向 a[1]。p+1 只计算地址，不改变 p。',
 'a 在 a+1 中转换为指向首元素的指针，计算结果同样指向 a[1]，但没有修改数组对象。',
 '自增需要可修改左值。数组不是可修改的指针变量，a++ 不满足要求，会导致约束错误。不能仅因为数组名常转换为指针就把它当成指针变量自增。'
],'进阶');
M(31,'meter','c-sizeof','下面 sizeof(a) 的值是多少？','char a[]="meter";',['5','6','由字符串指针大小决定','必须运行 strlen 才知道'],1,[
 '字符串字面量含 m、e、t、e、r 五个字符，并带有结尾零字符 \'\\0\'。用它初始化未指定长度的 char 数组，会把结尾零字符也放进去。',
 'a 因而是六元素 char 数组。sizeof 求数组对象占用的 C 字节数，sizeof(char) 恒为 1，所以结果 6。',
 'strlen(a) 只数第一个零字符前的字符，结果为 5；sizeof(a) 求的是整个数组空间。若改成 char *p=a，sizeof(p) 求指针大小，是另一回事。'
],'基础',{heads:['下标','存放的字符'],rows:[['0','m'],['1','e'],['2','t'],['3','e'],['4','r'],['5',"\\0（结尾零字符）"]]} );
M(32,'udp','n-tcpudp','哪项是通常所说的传输层无连接协议？','',['TCP','IP','UART','UDP'],3,[
 'UDP 在 IP 之上提供数据报传输，通过端口标识通信端点；协议不要求像 TCP 一样建立连接状态和完成握手。',
 'UDP 本身不保证可靠到达、有序或消除重复。应用可以在它之上自行实现确认重传，但这些不是 UDP 自动提供的可靠性。',
 'TCP 是传输层面向连接协议，IP 属于网络层，UART 是串行通信机制。题目同时问“传输层”和“无连接”，两项都要符合。'
]);
M(33,'volatile','c-keywords','在常见 MCU 编译器约定下，一个标志由 ISR 修改、主循环读取。哪项类型限定词用于表达需要保留这种特殊对象的访问语义？本题不把它当作完整并发保护。','/* ISR 写入 flag；主循环检查 flag */',['const','volatile','static','extern'],1,[
 '对编译器而言，普通代码分析可能看不到中断在何时更新变量。volatile 表达对象可能有这类外部变化，编译器需按其实现的 volatile 访问规则处理读写，不能像普通不变值一样简单消除所需访问。',
 'const 管理可修改性；static 在不同位置管理存储期或链接；extern 主要用于声明外部链接对象。这些都不能替代本题所问的访问限定。',
 'volatile 不保证读改写原子性，也不是线程同步或内存屏障。较宽变量可能不能一次原子读完，多字段状态也可能出现不一致；还要检查硬件、编译器约定，并采用临界区、原子操作或 RTOS 消息机制。'
],'进阶');

